import { useMemo, useState } from "react";
import { View } from "react-native";

import { LocatorMap } from "./components/locator-map";
import { StoreList } from "./components/store-list";
import { MAP_CENTER, stores } from "./data";

export default function Page() {
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(stores[0].id);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return stores;
    return stores.filter(
      (store) =>
        store.name.toLowerCase().includes(q) ||
        store.address.toLowerCase().includes(q) ||
        store.neighborhood.toLowerCase().includes(q),
    );
  }, [query]);

  return (
    <View className="h-screen flex-1 flex-row">
      <StoreList
        stores={filtered}
        query={query}
        onQueryChange={setQuery}
        selectedId={selectedId}
        onSelect={setSelectedId}
      />

      <View className="min-w-0 flex-1">
        <LocatorMap
          stores={filtered}
          selectedId={selectedId}
          onSelect={setSelectedId}
          onClearSelection={() => {
            setSelectedId(null);
          }}
          center={MAP_CENTER}
        />
      </View>
    </View>
  );
}

import { Clock, MapPin, Phone, Search } from "lucide-react-native";
import { Pressable, ScrollView, View } from "react-native";

import type { Store } from "../data";

import { Icon } from "@/components/ui/icon";
import { Input } from "@/components/ui/input";
import { Text } from "@/components/ui/text";
import { cn } from "@/lib/utils";

interface StoreListProps {
  stores: Store[];
  query: string;
  onQueryChange: (value: string) => void;
  selectedId: string | null;
  onSelect: (id: string) => void;
}

export function StoreList({
  stores,
  query,
  onQueryChange,
  selectedId,
  onSelect,
}: StoreListProps) {
  return (
    <View className="bg-sidebar border-sidebar-border w-80 shrink-0 border-r">
      <View className="gap-3 p-4">
        <View>
          <Text className="text-foreground text-lg font-semibold tracking-tight">
            Find a store
          </Text>
          <Text className="text-muted-foreground text-sm">
            {stores.length} {stores.length === 1 ? "location" : "locations"} near
            you
          </Text>
        </View>
        <View className="relative justify-center">
          <View className="absolute left-2.5 z-10">
            <Icon
              as={Search}
              size={16}
              className="text-muted-foreground"
            />
          </View>
          <Input
            value={query}
            onChangeText={onQueryChange}
            placeholder="Search name or address"
            className="bg-background pl-8"
            accessibilityLabel="Search stores"
          />
        </View>
      </View>

      <View className="bg-sidebar-border h-px" />

      <ScrollView className="flex-1 p-2">
        {stores.length === 0 ? (
          <View className="p-6">
            <Text className="text-muted-foreground text-center text-sm">
              No stores match your search.
            </Text>
          </View>
        ) : (
          <View className="gap-1">
            {stores.map((store) => {
              const active = store.id === selectedId;
              return (
                <Pressable
                  key={store.id}
                  onPress={() => {
                    onSelect(store.id);
                  }}
                  accessibilityState={{ selected: active }}
                  className={cn(
                    "gap-0 rounded-md p-3",
                    active && "bg-sidebar-accent",
                  )}
                >
                  <View className="flex-row items-center justify-between gap-2">
                    <Text className="text-foreground font-medium">
                      {store.name}
                    </Text>
                    <View className="flex-row items-center gap-1.5">
                      <View
                        className={cn(
                          "size-1.5 rounded-full",
                          store.openNow ? "bg-emerald-500" : "bg-neutral-500",
                        )}
                      />
                      <Text
                        className={cn(
                          "text-xs font-medium",
                          store.openNow
                            ? "text-foreground"
                            : "text-muted-foreground",
                        )}
                      >
                        {store.openNow ? "Open" : "Closed"}
                      </Text>
                    </View>
                  </View>

                  <View className="mt-2 gap-1.5">
                    <View className="flex-row items-center gap-1.5">
                      <Icon
                        as={MapPin}
                        size={14}
                        className="text-muted-foreground shrink-0"
                      />
                      <Text className="text-muted-foreground text-xs tabular-nums">
                        {store.address}, {store.neighborhood}
                      </Text>
                    </View>
                    <View className="flex-row items-center gap-1.5">
                      <Icon
                        as={Clock}
                        size={14}
                        className="text-muted-foreground shrink-0"
                      />
                      <Text className="text-muted-foreground text-xs tabular-nums">
                        {store.hours}
                      </Text>
                    </View>
                    <View className="flex-row items-center gap-1.5">
                      <Icon
                        as={Phone}
                        size={14}
                        className="text-muted-foreground shrink-0"
                      />
                      <Text className="text-muted-foreground text-xs tabular-nums">
                        {store.phone}
                      </Text>
                    </View>
                  </View>
                </Pressable>
              );
            })}
          </View>
        )}
      </ScrollView>
    </View>
  );
}

import { Clock, MapPin, Phone } from "lucide-react-native";
import { useEffect } from "react";
import { View } from "react-native";

import type { Store } from "../data";

import { Icon } from "@/components/ui/icon";
import { Text } from "@/components/ui/text";
import { cn } from "@/lib/utils";
import {
  Map,
  MapControls,
  MapMarker,
  MapPopup,
  MarkerContent,
  MarkerTooltip,
  useMap,
} from "@/components/ui/map";

interface LocatorMapProps {
  stores: Store[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onClearSelection: () => void;
  center: [number, number];
}

function FlyToSelected({ store }: { store?: Store }) {
  const { camera } = useMap();

  useEffect(() => {
    if (!camera || !store) return;
    camera.flyTo({
      center: [store.lng, store.lat],
      zoom: 14,
      duration: 800,
    });
  }, [camera, store]);

  return null;
}

function StorePin({ active }: { active: boolean }) {
  return (
    <View
      className={cn(
        "items-center justify-center rounded-full shadow-md",
        active ? "bg-foreground/80 size-9" : "bg-foreground size-7",
      )}
    >
      <Icon
        as={MapPin}
        size={active ? 18 : 14}
        className="text-background"
      />
    </View>
  );
}

export function LocatorMap({
  stores,
  selectedId,
  onSelect,
  onClearSelection,
  center,
}: LocatorMapProps) {
  const selected = stores.find((store) => store.id === selectedId);

  return (
    <View className="relative flex-1">
      <Map
        viewport={{ center, zoom: 12 }}
        minZoom={10}
        maxZoom={17}
      >
        <MapControls showCompass />
        <FlyToSelected store={selected} />

        {stores.map((store) => (
          <MapMarker
            key={store.id}
            longitude={store.lng}
            latitude={store.lat}
            onClick={() => {
              onSelect(store.id);
            }}
          >
            <MarkerContent>
              <StorePin active={store.id === selectedId} />
            </MarkerContent>
            <MarkerTooltip className="bg-foreground">
              <Text className="text-background">{store.name}</Text>
            </MarkerTooltip>
          </MapMarker>
        ))}

        {selected ? (
          <MapPopup
            longitude={selected.lng}
            latitude={selected.lat}
            closeButton
            closeOnClick={false}
            onClose={onClearSelection}
            className="min-w-56"
          >
            <Text className="text-popover-foreground pr-5 font-medium">
              {selected.name}
            </Text>
            <View
              className={cn(
                "mt-1 flex-row items-center gap-1.5",
                selected.openNow ? "text-foreground" : "text-muted-foreground",
              )}
            >
              <View
                className={cn(
                  "size-1.5 rounded-full",
                  selected.openNow ? "bg-emerald-500" : "bg-neutral-500",
                )}
              />
              <Text
                className={cn(
                  "text-xs font-medium",
                  selected.openNow
                    ? "text-foreground"
                    : "text-muted-foreground",
                )}
              >
                {selected.openNow ? "Open now" : "Closed"}
              </Text>
            </View>

            <View className="mt-2.5 gap-1.5">
              <View className="flex-row items-center gap-1.5">
                <Icon
                  as={MapPin}
                  size={14}
                  className="text-muted-foreground shrink-0"
                />
                <Text className="text-muted-foreground text-xs tabular-nums">
                  {selected.address}, {selected.neighborhood}
                </Text>
              </View>
              <View className="flex-row items-center gap-1.5">
                <Icon
                  as={Clock}
                  size={14}
                  className="text-muted-foreground shrink-0"
                />
                <Text className="text-muted-foreground text-xs tabular-nums">
                  {selected.hours}
                </Text>
              </View>
              <View className="flex-row items-center gap-1.5">
                <Icon
                  as={Phone}
                  size={14}
                  className="text-muted-foreground shrink-0"
                />
                <Text className="text-muted-foreground text-xs tabular-nums">
                  {selected.phone}
                </Text>
              </View>
            </View>
          </MapPopup>
        ) : null}
      </Map>
    </View>
  );
}
